  tete:{n:"Jeu de tête",i:"🗿",d:"Duels aériens plus souvent gagnés",pos:["ATT","DEF"],re:/tête|poteau/i},
  mur:{n:"Rempart",i:"🧱",d:"Tacles, pressing et interventions plus sûrs",pos:["DEF","MIL"],re:/tacle|serrer|presser|temporiser|faute|couper/i},
