function addSeed(id,i,branch,ev,d){ const c=EVENTS.find(e=>e.id===id).ch[i]; (branch?c.risk[branch]:c.fx).seed={ev,d}; }
addSeed("mentor",0,null,"mentorCoach",[5,9]);
